svg.metadata:
flowchart TB
  A["Browser: request an operation on a file"]
  B["Application API: authenticate, authorize the object and validate its key"]
  C["storage.presign: issue an expiring GET / PUT URL"]
  D["Browser: request S3 directly with that URL"]
  E["S3: verify signature and expiry, then transfer bytes"]
  X["Deny unauthorized, expired or mismatched requests"]
  A --> B
  B -->|"allowed"| C
  C --> D
  D --> E
  B -->|"denied"| X
  E -->|"verification fails"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
